    unlink(guard_out);
    if (choose_layout(&pick) != 0) {
        fprintf(stderr, "imprint: layout pick failed\n");
        return 1;
    }
    if (pick.from_bundle || permit_tag(pick.tag_value) != 0) {
        fprintf(stderr, "imprint: provenance rejected\n");
        return 1;
    }
    if (write_types_tab(pick.layout_path, types_out, pick.tag_value) != 0) {
        fprintf(stderr, "imprint: types write failed\n");
        return 1;
    }
    fp = fopen(tag_out, "w");
    if (!fp) {
        perror("imprint: procance.tag");
        return 1;
    }
    if (fprintf(fp, "%s\n", pick.tag_value) < 0 || fclose(fp) != 0) {
        fprintf(stderr, "imprint: procance write failed\n");
        return 1;
    }
    if (rebuild_binary() != 0) {
        fprintf(stderr, "imprint: rebuild failed\n");
        return 1;
    }
    fp = fopen(guard_out, "w");
    if (!fp) {
        perror("imprint: offline guard");
        return 1;
    }
    if (fputs("1\n", fp) == EOF || fclose(fp) != 0) {
        unlink(guard_out);
        return 1;
    }
    return 0;
}

